arguments.command:
# Write a C# script to parse the binlog
cat > /tmp/parse_binlog.csproj << 'EOF'
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net9.0</TargetFramework>
  </PropertyGroup>
  <ItemGroup>
    <PackageReference Include="MSBuild.StructuredLogger" Version="2.2.500" />
  </ItemGroup>
</Project>
EOF

cat > /tmp/parse_binlog.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Collections.Generic;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);
var errors = new List<(string project, string code, string message, string file, int line)>();
var warnings = new List<(string project, string code, string message, string file, int line)>();

build.VisitAllChildren<Error>(e => {
    var proj = "";
    var node = e.Parent;
    while (node != null) {
        if (node is Project p) { proj = p.Name; break; }
        if (node is Target t && t.Project is Project tp) { proj = tp.Name; break; }
        node = node.Parent as BaseNode;
    }
    errors.Add((proj, e.Code ?? "", e.Text ?? "", e.File ?? "", e.LineNumber ?? 0));
});

build.VisitAllChildren<Warning>(w => {
    var proj = "";
    var node = w.Parent;
    while (node != null) {
        if (node is Project p) { proj = p.Name; break; }
        if (node is Target t && t.Project is Project tp) { proj = tp.Name; break; }
        node = node.Parent as BaseNode;
    }
    warnings.Add((proj, w.Code ?? "", w.Text ?? "", w.File ?? "", w.LineNumber ?? 0));
});

Console.WriteLine("=== ERRORS ===");
foreach (var g in errors.GroupBy(e => e.project)) {
    Console.WriteLine($"\nProject: {g.Key}");
    foreach (var e in g) {
        Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
    }
}

Console.WriteLine("\n=== WARNINGS (potentially relevant) ===");
foreach (var g in warnings.GroupBy(w => w.project).Take(10)) {
    Console.WriteLine($"\nProject: {g.Key}");
    foreach (var w in g.Take(5)) {
        Console.WriteLine($"  [{w.code}] {w.file}({w.line}): {w.message}");
    }
    if (g.Count() > 5) Console.WriteLine($"  ... and {g.Count() - 5} more warnings");
}

// Also look at project dependencies / build order
Console.WriteLine("\n=== BUILD RESULT ===");
Console.WriteLine($"Build succeeded: {build.Succeeded}");

// Check for failed projects
build.VisitAllChildren<Project>(p => {
    // Check if project has errors
    var projErrors = new List<string>();
    p.VisitAllChildren<Error>(e => projErrors.Add(e.Code ?? ""));
    if (projErrors.Any()) {
        Console.WriteLine($"FAILED: {p.Name} - {projErrors.Count} error(s): {string.Join(", ", projErrors.Distinct())}");
    }
});
CSHARP

