cat > /tmp/parse_binlog2.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);

// Get all projects and their references
Console.WriteLine("=== PROJECT STRUCTURE ===");
build.VisitAllChildren<Project>(p => {
    Console.WriteLine($"\nProject: {p.Name}");
    p.VisitAllChildren<Item>(i => {
        if (i.Name == "PackageReference" || i.Name == "ProjectReference") {
            Console.WriteLine($"  {i.Name}: {i.Text}");
        }
    });
});

// Get the source file content from the binlog if available
Console.WriteLine("\n=== SOURCE CONTEXT (from error locations) ===");
build.VisitAllChildren<Error>(e => {
    Console.WriteLine($"Error in: {e.File} line {e.LineNumber}");
    Console.WriteLine($"  Code: {e.Code}");
    Console.WriteLine($"  Message: {e.Text}");
});

// Check for NuGet restore messages
Console.WriteLine("\n=== NUGET/RESTORE MESSAGES ===");
build.VisitAllChildren<Message>(m => {
    var text = m.Text ?? "";
    if (text.Contains("Newtonsoft", StringComparison.OrdinalIgnoreCase) ||
        text.Contains("PackageReference", StringComparison.OrdinalIgnoreCase) ||
        text.Contains("restore", StringComparison.OrdinalIgnoreCase)) {
        if (text.Length < 300)
            Console.WriteLine($"  {text}");
    }
});
