cat > /tmp/parse_binlog.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var build = BinaryLog.ReadBuild(args[0]);

// Get all items for each project to find actual PackageReference values
Console.WriteLine("=== PACKAGE REFERENCES PER PROJECT ===");
build.VisitAllChildren<NamedNode>(n => {
    if (n.Name == "PackageReference" && n is Folder f) {
        BaseNode node = n;
        var proj = "unknown";
        while (node != null) {
            if (node is Project p) { proj = p.Name; break; }
            node = (node as TreeNode)?.Parent;
        }
        Console.WriteLine($"\n  Project: {proj}");
        foreach (var child in f.Children) {
            Console.WriteLine($"    - {child}");
        }
    }
});

// Also check AddItem for PackageReference
Console.WriteLine("\n=== ADDED ITEMS ===");
build.VisitAllChildren<AddItem>(a => {
    if (a.Name == "PackageReference") {
        BaseNode node = a;
        var proj = "unknown";
        while (node != null) {
            if (node is Project p) { proj = p.Name; break; }
            node = (node as TreeNode)?.Parent;
        }
        Console.WriteLine($"  {proj}: AddItem PackageReference");
        foreach (var child in a.Children) {
            Console.WriteLine($"    {child}");
        }
    }
});

// Check project references
Console.WriteLine("\n=== PROJECT REFERENCES ===");
build.VisitAllChildren<AddItem>(a => {
    if (a.Name == "ProjectReference") {
        BaseNode node = a;
        var proj = "unknown";
        while (node != null) {
            if (node is Project p) { proj = p.Name; break; }
            node = (node as TreeNode)?.Parent;
        }
        Console.WriteLine($"  {proj} -> ");
        foreach (var child in a.Children) {
            Console.WriteLine($"    {child}");
        }
    }
});

// Show file paths from the binlog
Console.WriteLine("\n=== SOURCE FILES REFERENCED ===");
var files = new HashSet<string>();
build.VisitAllChildren<Item>(i => {
    if (i.Name == "Compile" && i.Text != null) {
        BaseNode node = i;
        var proj = "unknown";
        while (node != null) {
            if (node is Project p) { proj = p.Name; break; }
            node = (node as TreeNode)?.Parent;
        }
        files.Add($"  {proj}: {i.Text}");
    }
});
foreach (var f in files.OrderBy(x => x)) Console.WriteLine(f);
