# Let's try reading the csproj files directly from the binlog embedded files
cat > /tmp/parse_binlog.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);

// Try to get embedded files from the binlog
Console.WriteLine("=== EMBEDDED FILES ===");
var archiveFile = args[0];
var reader = new BinLogReader();
var records = reader.ReadRecords(archiveFile).ToList();

Console.WriteLine($"Total records: {records.Count}");

// Look for source file contents via EmbeddedFiles  
foreach (var record in records) {
    if (record?.Args is Microsoft.Build.Framework.BuildMessageEventArgs msg) {
        var text = msg.Message ?? "";
        if (text.Contains("PackageReference") && !text.Contains("_RestoreSolution") && text.Length < 500) {
            Console.WriteLine($"MSG: {text}");
        }
    }
}

// Try reading the archive
Console.WriteLine("\n=== ARCHIVE FILES ===");
try {
    var embeddedFiles = reader.ReadRecords(archiveFile)
        .Where(r => r.Args is Microsoft.Build.Framework.ProjectStartedEventArgs)
        .Select(r => r.Args as Microsoft.Build.Framework.ProjectStartedEventArgs)
        .Where(p => p != null);

    foreach (var ps in embeddedFiles) {
        Console.WriteLine($"Project: {ps.ProjectFile}");
        if (ps.Properties != null) {
            var props = ps.Properties.Cast<KeyValuePair<string, string>>()
                .Where(kv => kv.Key.Contains("Package", StringComparison.OrdinalIgnoreCase) || 
                            kv.Key.Contains("Newtonsoft", StringComparison.OrdinalIgnoreCase))
                .Take(10);
            foreach (var kv in props) {
                Console.WriteLine($"  Prop: {kv.Key} = {kv.Value}");
            }
        }
        if (ps.Items != null) {
            var items = ps.Items.Cast<KeyValuePair<string, IEnumerable<KeyValuePair<string, string>>>>()
                .Where(kv => kv.Key == "PackageReference");
            foreach (var itemGroup in items) {
                Console.WriteLine($"  ItemGroup: {itemGroup.Key}");
                foreach (var item in itemGroup.Value) {
                    Console.WriteLine($"    {item.Key} = {item.Value}");
                }
            }
        }
    }
} catch (Exception ex) {
    Console.WriteLine($"Error: {ex.Message}");
}
