    if (record.Args is Microsoft.Build.Framework.ProjectStartedEventArgs ps && ps.ProjectFile != null) {
        var key = ps.ProjectFile;
        if (!seenProjects.Add(key)) continue;
        if (!key.EndsWith(".csproj")) continue;

        Console.WriteLine($"\n=== {System.IO.Path.GetFileName(key)} ===");

        if (ps.Items != null) {
            foreach (DictionaryEntry entry in ps.Items) {
                var itemType = entry.Key?.ToString();
                if (itemType == "PackageReference" || itemType == "ProjectReference") {
                    Console.WriteLine($"  {itemType}:");
                    if (entry.Value is IEnumerable items) {
                        foreach (DictionaryEntry item in items) {
                            Console.WriteLine($"    {item.Key}");
                        }
                    }
                }
            }
        }
    }
}

