foreach (var record in archiveReader.ReadRecords(args[0])) {
    if (record.Args is Microsoft.Build.Framework.BuildMessageEventArgs msg) {
        var text = msg.Message ?? "";
        if (text.StartsWith("Csc") && text.Contains(".cs")) {
            Console.WriteLine($"  {text.Substring(0, Math.Min(text.Length, 200))}");
        }
    }
}
