            Console.WriteLine($"  Items type: {ps.Items.GetType()}");
            var count = 0;
            foreach (var entry in ps.Items) {
                if (count++ > 3) { Console.WriteLine("  ... (more items)"); break; }
                Console.WriteLine($"  Entry type: {entry?.GetType()}, value: {entry}");
                // Try reflection
                if (entry != null) {
                    var t = entry.GetType();
                    var props = t.GetProperties();
                    foreach (var p in props) {
                        try {
                            var val = p.GetValue(entry);
                            Console.WriteLine($"    .{p.Name} = {val}");
                        } catch {}
                    }
                }
            }
        }
    }
}
