        Console.WriteLine($"  Embedded: {path}");
        // Write content
        var outPath = Path.Combine(archiveFilesDir, Path.GetFileName(path));
        File.WriteAllBytes(outPath, content.ToArray());
    }
} catch (Exception ex) {
    Console.WriteLine($"  Error: {ex.Message}");
