    var text = n.ToString() ?? "";
    if (text.Contains("Newtonsoft", StringComparison.OrdinalIgnoreCase) && 
        !text.Contains("NuGet.Build.Tasks") &&
        !text.Contains("Assembly loaded")) {
        Console.WriteLine($"  [{n.GetType().Name}] {text.Substring(0, Math.Min(text.Length, 200))}");
    }
});

// Extract embedded files from the binlog
Console.WriteLine("\n=== EXTRACTING EMBEDDED FILES ===");
try {
    var archiveFilesDir = "/tmp/binlog_files";
    Directory.CreateDirectory(archiveFilesDir);
    var embeddedFiles = BinaryLog.ReadEmbeddedFiles(args[0]);
    foreach (var (path, content) in embeddedFiles) {
        Console.WriteLine($"  Embedded: {path}");
        // Write content
        var outPath = Path.Combine(archiveFilesDir, Path.GetFileName(path));
        File.WriteAllBytes(outPath, content.ToArray());
    }
} catch (Exception ex) {
    Console.WriteLine($"  Error: {ex.Message}");
}
