cat > /tmp/parse_binlog.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);

// Search the tree for Newtonsoft
Console.WriteLine("=== SEARCHING TREE FOR NEWTONSOFT ===");
build.VisitAllChildren<BaseNode>(n => {
    var text = n.ToString() ?? "";
    if (text.Contains("Newtonsoft", StringComparison.OrdinalIgnoreCase) && 
        !text.Contains("NuGet.Build.Tasks") &&
        !text.Contains("Assembly loaded")) {
        Console.WriteLine($"  [{n.GetType().Name}] {text.Substring(0, Math.Min(text.Length, 300))}");
    }
});

// Find the SourceFilesArchive in tree
Console.WriteLine("\n=== LOOKING FOR SOURCE FILES ARCHIVE ===");
build.VisitAllChildren<BaseNode>(n => {
    if (n.GetType().Name.Contains("Archive") || n.GetType().Name.Contains("Source")) {
        Console.WriteLine($"  [{n.GetType().Name}] {n}");
    }
});

// Try to find project file content via embedded content
Console.WriteLine("\n=== LOOKING FOR .CSPROJ CONTENT ===");
var reader = new BinLogReader();
foreach (var record in reader.ReadRecords(args[0])) {
    if (record.Args is Microsoft.Build.Framework.ProjectEvaluationFinishedEventArgs eval) {
        Console.WriteLine($"  Eval finished: {eval.ProjectFile}");
    }
}

// Read the SourceFiles archive from the binlog directly
Console.WriteLine("\n=== READING BINLOG ARCHIVE ===");
var archives = BinaryLog.ReadBuild(args[0]).FindChild<SourceFilesArchive>();
if (archives != null) {
    Console.WriteLine($"Found archive with {archives.Children.Count} children");
    foreach (var child in archives.Children) {
        Console.WriteLine($"  {child.GetType().Name}: {child}");
        // Try to get the text
        if (child is ArchiveFile af) {
            Console.WriteLine($"    FullPath: {af.FullPath}");
            var text = af.Text ?? "";
            Console.WriteLine($"    Content ({text.Length} chars):");
            Console.WriteLine(text.Substring(0, Math.Min(text.Length, 1000)));
            Console.WriteLine();
        }
    }
}
CSHARP

