# Let's look for the csproj file content embedded in the binlog, and all restore-related details
cat > /tmp/parse_binlog.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);

// Look for embedded project files
Console.WriteLine("=== LOOKING FOR EMBEDDED FILES ===");
build.VisitAllChildren<BaseNode>(n => {
    var typeName = n.GetType().Name;
    if (typeName == "ArchiveFile" || typeName == "EmbeddedFile" || typeName == "SourceFile") {
        Console.WriteLine($"  [{typeName}] {n}");
    }
});

// Look at NuGet restore details - what packages were restored
Console.WriteLine("\n=== NUGET RESTORE DETAILS ===");
build.VisitAllChildren<Message>(m => {
    var text = m.Text ?? "";
    if ((text.Contains("Installing") || text.Contains("Restored") || text.Contains("package") || 
         text.Contains("assets file") || text.Contains("project.assets")) &&
        text.Length < 300) {
        Console.WriteLine($"  {text}");
    }
});

// Look at the Csc task invocations for references
Console.WriteLine("\n=== CSC REFERENCES (for Services.csproj) ===");
build.VisitAllChildren<Task>(t => {
    if (t.Name != "Csc") return;
    // Check if this is for Services
    BaseNode node = t;
    var proj = "";
    while (node != null) {
        if (node is Project p) { proj = p.Name; break; }
        node = (node as TreeNode)?.Parent;
    }
    if (!proj.Contains("Services")) return;

    Console.WriteLine($"  Csc task in {proj}:");
    t.VisitAllChildren<BaseNode>(n => {
        var text = n.ToString() ?? "";
        if (text.Contains("Reference") || text.Contains("Newtonsoft") || text.Contains(".dll")) {
            if (text.Length < 300)
                Console.WriteLine($"    [{n.GetType().Name}] {text}");
        }
    });
});

// Look at project file imports - specifically for Services.csproj
Console.WriteLine("\n=== SERVICES.CSPROJ IMPORTS ===");
build.VisitAllChildren<ProjectEvaluation>(pe => {
    if (!pe.Name.Contains("Services")) return;
    Console.WriteLine($"  Eval: {pe.Name}");
    pe.VisitAllChildren<BaseNode>(n => {
        var text = n.ToString() ?? "";
        if (text.Contains("Newtonsoft") || text.Contains("Json")) {
            Console.WriteLine($"    [{n.GetType().Name}] {text.Substring(0, Math.Min(text.Length, 200))}");
        }
    });
});
CSHARP

