cat > /tmp/parse_binlog.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);

// Check if Api.csproj built at all or was skipped due to Services failure
Console.WriteLine("=== BUILD STATUS PER PROJECT ===");
build.VisitAllChildren<Project>(p => {
    var succeeded = true;
    var errorCount = 0;
    p.VisitAllChildren<Error>(_ => { errorCount++; succeeded = false; });

    // Check for "skipped" or "not built" targets
    var hasTargets = false;
    p.VisitAllChildren<Target>(t => {
        if (t.Name == "CoreCompile" || t.Name == "Build" || t.Name == "Csc") {
            hasTargets = true;
            Console.WriteLine($"  {p.Name}: Target {t.Name} (Succeeded={t.Succeeded})");
        }
    });
});

// Source file content from the binlog
Console.WriteLine("\n=== SOURCE FILE: UserService.cs (from error context) ===");
build.VisitAllChildren<Error>(e => {
    Console.WriteLine($"  File: {e.File}");
    Console.WriteLine($"  Line: {e.LineNumber}, Col: {e.ColumnNumber}");
    Console.WriteLine($"  Code: {e.Code}");
    Console.WriteLine($"  Msg: {e.Text}");
    Console.WriteLine();
});

// Check the project target framework
Console.WriteLine("=== TARGET FRAMEWORK ===");
build.VisitAllChildren<Property>(p => {
    if (p.Name == "TargetFramework" || p.Name == "TargetFrameworkVersion") {
        BaseNode node = p;
        var proj = "";
        while (node != null) {
            if (node is Project pr) { proj = pr.Name; break; }
            if (node is ProjectEvaluation pe) { proj = pe.Name; break; }
            node = (node as TreeNode)?.Parent;
        }
        Console.WriteLine($"  {proj}: {p.Name} = {p.Value}");
    }
});
